/*
 * 荔枝FM (m.lizhi.fm) 原生 Ceru v2 插件
 * 站点：https://m.lizhi.fm/vodapi（播客/电台/有声书）
 * 音质：64k(SD M4A) / 128k(HD MP3)
 *
 * 实测（2026-11-19）：
 *   搜索: GET /vodapi/search/voice?deviceId=&keywords={kw}&page=&receiptData= → code=0, data[]
 *          条目为平铺结构：voiceInfo / voicePlayProperty / userInfo / voiceExProperty
 *          ⚠️ page 参数被上游忽略，翻页仅由 receiptData 驱动且每页条数不固定（实测 18/13/6…）
 *          → 按关键词维护会话缓冲，宿主第 N 页 = 缓冲第 N 个定长切片；receiptData 为空即到底
 *   详情: GET /vodapi/voci/info/{voiceId}
 *   取链: trackUrl=http://cdn5.lizhi.fm/audio/YYYY/MM/DD/{voiceId}_hd.mp3
 *          派生 SD：_hd.mp3 → _sd.m4a（同一 CDN 路径，仅后缀不同）
 *   音质实测（4 首一致）: HD MP3 魔数 ID3、128.3~133.5kbps；SD M4A、14.4~14.8kbps
 *          SD 实测仅 14.5kbps，宿主内置键最低档即 64k，无更低标签可用 → 落 64k 并在注释写明实测值
 *   封面: cdnimg101.gzlzfm.com/audio_cover/YYYY/MM/DD/*.jpg（页面直给）
 *   付费条目 trackUrl 为空 → 用封面 URL 的 /YYYY/MM/DD/ 日期段派生直链（CDN 不校验付费态）
 *   CDN 风控: iPhone Safari UA 一律 403；Android Chrome UA 高频会被临时拉黑；
 *          okhttp/4.10.0 API 与 CDN 全链可用 → 统一 okhttp UA，403 时 UA 池轮换自愈
 *   歌词: 无（播客/电台内容）
 */
exports.manifest = {
  manifestVersion: 2,
  id: 'ceru.lizhi',
  name: '荔枝FM',
  version: '1.0.0',
  description: '支持音质：64k/128k',
  author: 'hebijunge',
  engines: { hostApi: '^2.0.0', logicRuntime: 'ceru-js@1' },
  modules: { logic: { entry: 'logic.main' } },
  permissions: [{ key: 'network', name: 'network.request', reason: '搜索与取链需要访问网络' }],
  contributes: {
    providers: [{
      id: "ceru.lizhi",
      name: '荔枝FM',
      protocols: ['music.search@1', 'music.resolve@1'],
      qualities: ['64k', '128k'],
      connectionMode: 'none'
    }]
  }
};

